using EduManageLms.Api.Common; using EduManageLms.Api.Domain; using EduManageLms.Api.Infrastructure; using MongoDB.Driver;
namespace EduManageLms.Api.Application;
public sealed class GradebookService(MongoContext db):IGradebookService{
 public async Task<GradebookDto> GetAsync(string lecturerCode,string? sectionId,CancellationToken ct){var f=Builders<ClassSection>.Filter.Eq(x=>x.LecturerCode,lecturerCode)&Builders<ClassSection>.Filter.Eq(x=>x.IsDeleted,false);if(!string.IsNullOrWhiteSpace(sectionId)&&sectionId!="default")f&=Builders<ClassSection>.Filter.Eq(x=>x.Id,sectionId);var section=await db.ClassSections.Find(f).FirstOrDefaultAsync(ct)??throw new NotFoundException("Không tìm thấy lớp học phần được phân công");var students=await db.Students.Find(Builders<Student>.Filter.In(x=>x.StudentCode,section.Students.Select(s=>s.StudentCode))).ToListAsync(ct);var rows=students.Select(s=>{var c=s.AcademicRecords.SelectMany(y=>y.Semesters).SelectMany(y=>y.Courses).FirstOrDefault(y=>y.ClassSectionId==section.Id);var scores=section.GradingSchemeSnapshot.Components.ToDictionary(x=>x.ComponentId,x=>c?.Scores.FirstOrDefault(z=>z.ComponentId==x.ComponentId)?.Score);var final=section.GradingSchemeSnapshot.Components.Sum(x=>((scores[x.ComponentId]??0)/x.MaxScore)*10*(x.Weight/100));return new GradebookStudentDto(s.Id,s.StudentCode,s.FullName,scores,Math.Round(final,2),Letter(final),final>=section.GradingSchemeSnapshot.PassingScore);}).ToList();return new(section.Id,section.ClassSectionCode,section.CourseName,section.GradeStatus,section.GradingSchemeSnapshot.Components.Select(x=>new GradebookComponentDto(x.ComponentId,x.Name,x.Weight,x.MaxScore)).ToList(),rows);}
 public async Task UpdateAsync(string lecturerCode,string sectionId,GradeUpdateRequest r,string userId,CancellationToken ct){var section=await db.ClassSections.Find(x=>x.Id==sectionId&&x.LecturerCode==lecturerCode&&!x.IsDeleted).FirstOrDefaultAsync(ct)??throw new NotFoundException();if(section.GradeStatus=="Locked")throw new ForbiddenException("Bảng điểm đã khóa");foreach(var row in r.Students){var student=await db.Students.Find(x=>x.Id==row.StudentId&&!x.IsDeleted).FirstOrDefaultAsync(ct)??throw new NotFoundException("Sinh viên không tồn tại");if(!section.Students.Any(x=>x.StudentId==student.Id))throw new ForbiddenException("Sinh viên không thuộc lớp");var course=student.AcademicRecords.SelectMany(x=>x.Semesters).SelectMany(x=>x.Courses).FirstOrDefault(x=>x.ClassSectionId==section.Id)??throw new NotFoundException("Không có hồ sơ môn học");foreach(var entry in row.Scores){var def=section.GradingSchemeSnapshot.Components.FirstOrDefault(x=>x.ComponentId==entry.Key)??throw new AppException($"Cột điểm {entry.Key} không hợp lệ");if(entry.Value is <0||entry.Value>def.MaxScore)throw new AppException($"Điểm {def.Name} phải từ 0 đến {def.MaxScore}");var score=course.Scores.First(x=>x.ComponentId==entry.Key);score.Score=entry.Value;score.Status=entry.Value.HasValue?"Graded":"NotGraded";}course.ScoreStatus=r.Publish?"Published":"InProgress";course.PublishedAt=r.Publish?DateTime.UtcNow:null;student.UpdatedAt=DateTime.UtcNow;await db.Students.ReplaceOneAsync(x=>x.Id==student.Id,student,cancellationToken:ct);}section.GradeStatus=r.Publish?"Published":"InProgress";await db.ClassSections.ReplaceOneAsync(x=>x.Id==section.Id,section,cancellationToken:ct);await db.AuditLogs.InsertOneAsync(new(){UserId=userId,Role="Lecturer",Action=r.Publish?"PublishGrades":"SaveGrades",Entity="ClassSection",EntityId=section.Id,After=new{count=r.Students.Count}},cancellationToken:ct);}
 private static string Letter(double s)=>s>=8.5?"A":s>=8?"B+":s>=7?"B":s>=6.5?"C+":s>=5.5?"C":s>=5?"D+":s>=4?"D":"F";
}
